package clients
import("context";"fmt";"net/http";"net/http/httptest";"testing";"github.com/jahla2/Xentra/backend/control-plane/internal/domain")
type fakeGitHubTokenProvider struct{}
func(fakeGitHubTokenProvider)GetGitHubToken(context.Context,string)(string,error){return "token",nil}
func TestGitHubClientBuildsCommitAndWorkflowTimeline(t *testing.T){server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if r.Header.Get("Authorization")!="Bearer token"{t.Fatal("missing token")};w.Header().Set("Content-Type","application/json");if r.URL.Path=="/repos/acme/api/commits"{fmt.Fprint(w,`[{"html_url":"https://github/commit/1","commit":{"message":"fix prod\nbody","author":{"date":"2026-09-18T00:00:00Z"}}}]`);return};if r.URL.Path=="/repos/acme/api/actions/runs"{fmt.Fprint(w,`{"workflow_runs":[{"name":"deploy","status":"completed","conclusion":"failure","html_url":"https://github/run/1","created_at":"2026-09-18T00:01:00Z"}]}`);return};http.NotFound(w,r)}));defer server.Close();client:=NewGitHubClientWithBaseURL(fakeGitHubTokenProvider{},server.URL);events,err:=client.FetchTimeline(context.Background(),domain.RepositoryIntegration{Owner:"acme",Repo:"api",CredentialID:"cred"});if err!=nil{t.Fatal(err)};if len(events)!=2||events[0].Kind!="commit"||events[1].Kind!="workflow"{t.Fatalf("unexpected timeline: %#v",events)}}
